   441  static int
   442  is_mach_o_magic(struct elf_header *h,
   443      unsigned *endian,
   444      unsigned *offsetsize)
   445  {
   446      unsigned long magicval = 0;
   447      unsigned locendian = 0;
   448      unsigned locoffsetsize = 0;
   449
   450      /*  No swapping here. Need to match size of
   451          Mach-o magic field. */
   452      magicval = magic_copy(h->e_ident,4);
   453      if (magicval == MH_MAGIC) {
   454          locendian = DW_END_big;
   455          locoffsetsize = 32;
   456      } else if (magicval == MH_CIGAM) {
   457          locendian = DW_END_little;
   458          locoffsetsize = 32;
   459      }else if (magicval == MH_MAGIC_64) {
   460          locendian = DW_END_big;
   461          locoffsetsize = 64;
   462      } else if (magicval == MH_CIGAM_64) {
   463          locendian = DW_END_little;
   464          locoffsetsize = 64;
   465      } else {
   466          return FALSE;
   467      }
   468      *endian = locendian;
   469      *offsetsize = locoffsetsize;
   470      return TRUE;
   471  }
