   473  int
   474  dwarf_object_detector_fd(int fd,
   475      unsigned *ftype,
   476      unsigned *endian,
   477      unsigned *offsetsize,
   478      Dwarf_Unsigned  *filesize,
   479      int *errcode)
   480  {
   481      struct elf_header h;
   482      size_t readlen = sizeof(h);
   483      int res = 0;
   484      off_t fsize = 0;
   485      off_t lsval = 0;
   486      ssize_t readval = 0;
   487
   488      fsize = lseek(fd,0L,SEEK_END);
   489      if (fsize < 0) {
   490          *errcode = DW_DLE_SEEK_ERROR;
   491          return DW_DLV_ERROR;
   492      }
   493      if (fsize <= (off_t)readlen) {
   494          /* Not a real object file */
   495          *errcode = DW_DLE_FILE_TOO_SMALL;
   496          return DW_DLV_ERROR;
   497      }
   498      lsval  = lseek(fd,0L,SEEK_SET);
   499      if (lsval < 0) {
   500          *errcode = DW_DLE_SEEK_ERROR;
   501          return DW_DLV_ERROR;
   502      }
   503      readval = read(fd,&h,readlen);
   504      if (readval != (ssize_t)readlen) {
   505          *errcode = DW_DLE_READ_ERROR;
   506          return DW_DLV_ERROR;
   507      }
   508      if (h.e_ident[0] == 0x7f &&
   509          h.e_ident[1] == 'E' &&
   510          h.e_ident[2] == 'L' &&
   511          h.e_ident[3] == 'F') {
   512          /* is ELF */
   513
   514          res = fill_in_elf_fields(&h,endian,offsetsize,errcode);
   515          if (res != DW_DLV_OK) {
   516              return res;
   517          }
   518          *ftype = DW_FTYPE_ELF;
   519          *filesize = (size_t)fsize;
   520          return DW_DLV_OK;
   521      }
   522      if (is_mach_o_magic(&h,endian,offsetsize)) {
   523          *ftype = DW_FTYPE_MACH_O;
   524          *filesize = (size_t)fsize;
   525          return DW_DLV_OK;
   526      }
   527      if (is_archive_magic(&h)) {
   528          *ftype = DW_FTYPE_ARCHIVE;
   529          *filesize = (size_t)fsize;
   530          return DW_DLV_OK;
   531      }
   532      res = is_pe_object(fd,fsize,endian,offsetsize,errcode);
   533      if (res == DW_DLV_OK ) {
   534          *ftype = DW_FTYPE_PE;
   535          *filesize = (size_t)fsize;
   536          return DW_DLV_OK;
   537      }
   538      /* Unknown object format. */
   539      return DW_DLV_NO_ENTRY;
   540  }
